WITH src AS (SELECT *, LAST_DAY(sale_date) AS sale_date_month_end FROM store_sales WHERE product_id IN (3, 6, 7)), sale_quarter_summary AS (SELECT QUARTER(sale_date) AS sale_quarter, product_id, AVG(revenue) AS avg_revenue, MAX(sale_date) AS last_sale_date FROM src GROUP BY QUARTER(sale_date), product_id) SELECT sale_quarter, product_id, avg_revenue, last_sale_date FROM sale_quarter_summary ORDER BY product_id;
